Q: Zoho Survey invokeurl returns “.json” filename (responseText) instead of inline JSON when generating unique URL from trigger function A: <p>Turns out I had to go through Zoho Creator. I made this workflow function:</p>
<pre><code>string function_get_unique_url(string response_id)
{
    // Get access token
    clientId = &quot;r&quot;;
    clientSecret = &quot;r&quot;;
    refreshToken = &quot;r&quot;;
    tokenResp = invokeurl
    [
        url :&quot;https://accounts.zoho.com/oauth/v2/token&quot;
        type :POST
        parameters:{&quot;refresh_token&quot;:refreshToken,&quot;client_id&quot;:clientId,&quot;client_secret&quot;:clientSecret,&quot;grant_type&quot;:&quot;refresh_token&quot;}
    ];
    accessToken = ifnull(tokenResp.get(&quot;access_token&quot;),&quot;&quot;).toString();
    // Build payload
    respondentsList = List();
    oneRec = Map();
    oneRec.put(&quot;id&quot;,response_id);
    respondentsList.add(oneRec);
    payload = Map();
    payload.put(&quot;respondentsList&quot;,respondentsList);
    // Call survey API
    resp = invokeurl
    [
        url :&quot;[survey url]&quot;
        type :POST
        parameters:payload.toString()
        headers:{&quot;Accept&quot;:&quot;application/json&quot;,&quot;Authorization&quot;:&quot;Zoho-oauthtoken &quot; + accessToken}
        detailed:true
        content-type:&quot;application/json&quot;
    ];
    // Extract url
    raw = ifnull(resp,&quot;&quot;).toString();
    shortUrl = &quot;&quot;;
    p = raw.indexOf(&quot;https://&quot;);
    if(p != -1)
    {
        tmp = raw.substring(p,raw.length());
        q = tmp.indexOf(&quot;\&quot;&quot;);
        if(q != -1)
        {
            shortUrl = tmp.substring(0,q);
            shortUrl = shortUrl.replaceAll(&quot;\\&quot;,&quot;&quot;);
        }
    }
    return shortUrl;
}
</code></pre>
<p>And then added the below to my survey trigger function code:</p>
<pre><code>creatorUrl = &quot;[url to function]&quot;;
args = Map();
args.put(&quot;response_id&quot;,responseId.toString());
bodyMap = Map();
bodyMap.put(&quot;arguments&quot;,args);
creatorResp = invokeurl
[
    url :creatorUrl
    type :POST
    parameters:bodyMap.toString()
    headers:{&quot;Accept&quot;:&quot;application/json&quot;}
    detailed:true
    connection:&quot;surveycreator&quot;
    content-type:&quot;application/json&quot;
];
uniqueURL = creatorResp.get(&quot;responseText&quot;).get(&quot;result&quot;);
</code></pre>
